# 2️⃣  Custom CUDA kernel for 1‑D convolution (naïve but functional)
# -------------------------------------------------------------------------
conv1d_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void conv1d_kernel(const float* __restrict__ input,
                               const float* __restrict__ weight,
                               const int weight_h, const int weight_w,
                               const float* __restrict__ bias,
                               float* output,
                               int batch_size,
                               int in_channels,
                               int out_channels,
                               int kernel_size,
                               int stride,
                               int dilation,
                               int length) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch_size * out_channels * length) return;

    int tmp = idx;
    int out_pos = tmp % length;
    tmp /= length;
    int out_ch = tmp % out_channels;
    tmp /= out_channels;
    int batch = tmp;

    float sum = 0.0f;
    for (int k = 0; k < kernel_size; ++k) {
        int w_idx = out_ch * kernel_size + k + k * dilation;
        if (w_idx < weight_h * weight_w) {
            sum += input[b * in_channels * length + out_ch * kernel_size + k + k * dilation] *
                   weight[w_idx];
        }
    }

    if (bias) {
        sum += bias[batch * out_channels * length + out_ch * length + out_pos];
    }

    output[idx] = sum;
}
"""

conv1d_kernel_cuda_source = """
torch::Tensor conv1d_cuda(torch::Tensor input, int out_channels, int kernel_size, int stride, int dilation, bool bias, int in_channels) {
    auto in_shape = input.shape();
    int B = in_shape[0];
    int C_in = in_shape[1];
    int L = in_shape[2];
    int O_C = out_channels;
    int K = kernel_size;
    int S = stride;
    int D = dilation;
    int L_out = (L - (K - 1) * D) // S + 1;
    if (L_out <= 0) L_out = 1;

    auto out = torch::zeros_like(input);

    const int block_size = 256;
    const int num_blocks = (B * O_C * L_out + block_size - 1) / block_size;

    conv1d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        nullptr,          // weight not supplied – placeholder
        0,                // weight_h
        0,                // weight_w
        out.data_ptr<float>(),
        B,
        C_in,
        O_C,
        K,
        S,
        D,
        L_out
    );

    return out;
}
"""

